/* Introduction to Cybersecurity: 12 modules for first-year students. All text is T(en,fr,ar). Fictional scenarios only. */
(function(){
const {T}=CKI;const C=window.CKC;
const Q=(q,o,a,why)=>({q,opts:o,a,why});
const G=(t,d)=>[t,d];
const M=(id,icon,title,obj,body,gloss,act,quiz,sum,extra)=>Object.assign({id,icon,title,obj,body,gloss,act,quiz,sum},extra||{});

C.course=[
M('m1','shield',T('What Is Cybersecurity?','Qu’est-ce que la cybersécurité ?','ما هو الأمن السيبراني؟'),
 [T('Define cybersecurity and compare it with information security and privacy.','Définir la cybersécurité et la comparer à la sécurité de l’information et à la vie privée.','تعريف الأمن السيبراني ومقارنته بأمن المعلومات والخصوصية.'),T('Recognize common myths, ethical use and career paths.','Reconnaître les idées reçues, l’usage éthique et les métiers.','التعرف على المفاهيم الخاطئة والاستخدام الأخلاقي والمسارات المهنية.')],
 [T('Cybersecurity protects devices, networks and data from misuse, damage and theft. It matters at university (grades, research), in business (customer data), in government (public services) and on your phone (photos, messages).','La cybersécurité protège appareils, réseaux et données contre l’abus, les dégâts et le vol. Elle compte à l’université (notes, recherche), en entreprise (données clients), dans l’administration (services publics) et sur ton téléphone (photos, messages).','يحمي الأمن السيبراني الأجهزة والشبكات والبيانات من إساءة الاستخدام والتلف والسرقة. وهو مهم في الجامعة (العلامات والبحث) وفي الشركات (بيانات الزبائن) وفي الحكومة (الخدمات العامة) وعلى هاتفك (الصور والرسائل).'),
  T('Information security protects information in any form, even paper. Privacy decides who may use your personal data. Myth: “attackers only target big companies”. In reality most attacks are automated and hit everyone, so every account counts. Always use skills ethically and with permission.','La sécurité de l’information protège l’information sous toute forme, même papier. La vie privée décide qui peut utiliser tes données personnelles. Mythe : « les attaquants visent seulement les grandes entreprises ». En réalité, la plupart des attaques sont automatiques et touchent tout le monde. Utilise toujours tes compétences de façon éthique et autorisée.','يحمي أمن المعلومات المعلومات بأي شكل حتى الورق. أما الخصوصية فتحدد من يحق له استخدام بياناتك الشخصية. خرافة: «المهاجمون يستهدفون الشركات الكبيرة فقط». الحقيقة أن معظم الهجمات آلية وتصيب الجميع، فكل حساب مهم. استخدم مهاراتك دائماً بأخلاق وبإذن.')],
 [G(T('Cybersecurity','Cybersécurité','الأمن السيبراني'),T('Protecting digital systems and data.','Protéger systèmes numériques et données.','حماية الأنظمة الرقمية والبيانات.')),G(T('Information security','Sécurité de l’information','أمن المعلومات'),T('Protecting information in any form.','Protéger l’information sous toute forme.','حماية المعلومات بأي شكل.')),G(T('Privacy','Vie privée','الخصوصية'),T('Control over your personal data.','Contrôle de tes données personnelles.','التحكم في بياناتك الشخصية.'))],
 Q(T('A classmate says: “My laptop has nothing important, nobody would attack it.” Best reply?','Un camarade dit : « Mon portable n’a rien d’important, personne ne l’attaquerait. » Meilleure réponse ?','زميل يقول: «حاسوبي لا يحوي شيئاً مهماً ولن يهاجمه أحد». أفضل رد؟'),[T('Correct, skip updates.','Exact, pas de mises à jour.','صحيح، تجاهل التحديثات.'),T('Attacks are often automated, and your accounts and files have value.','Les attaques sont souvent automatiques et tes comptes et fichiers ont de la valeur.','الهجمات غالباً آلية وحساباتك وملفاتك لها قيمة.'),T('Only antivirus matters.','Seul l’antivirus compte.','مكافح الفيروسات وحده يكفي.')],1,T('Automated attacks scan everyone. Your email, university account and files are worth protecting.','Les attaques automatiques ciblent tout le monde. Ton e-mail, ton compte universitaire et tes fichiers méritent d’être protégés.','الهجمات الآلية تفحص الجميع. بريدك وحسابك الجامعي وملفاتك تستحق الحماية.')),
 [Q(T('Which concept is about who may use your personal data?','Quel concept concerne qui peut utiliser tes données personnelles ?','أي مفهوم يتعلق بمن يحق له استخدام بياناتك الشخصية؟'),[T('Privacy','Vie privée','الخصوصية'),T('Bandwidth','Bande passante','عرض النطاق')],0,T('Privacy is about control over personal data.','La vie privée, c’est le contrôle des données personnelles.','الخصوصية هي التحكم في البيانات الشخصية.')),
  Q(T('Which is a cybersecurity career?','Lequel est un métier de la cybersécurité ?','أي من التالي مهنة في الأمن السيبراني؟'),[T('Font designer','Designer de polices','مصمم خطوط'),T('SOC analyst','Analyste SOC','محلل مركز عمليات الأمن')],1,T('A SOC analyst monitors alerts and investigates incidents.','Un analyste SOC surveille les alertes et enquête sur les incidents.','يراقب محلل SOC التنبيهات ويحقق في الحوادث.'))],
 T('Cybersecurity protects systems and data; ethics and permission always come first.','La cybersécurité protège systèmes et données ; l’éthique et l’autorisation passent toujours en premier.','يحمي الأمن السيبراني الأنظمة والبيانات، والأخلاق والإذن أولاً دائماً.')),

M('m2','lock',T('The CIA Triad and Security Fundamentals','La triade CIA et les bases de la sécurité','ثالوث CIA وأساسيات الأمن'),
 [T('Explain confidentiality, integrity and availability with examples.','Expliquer confidentialité, intégrité et disponibilité avec des exemples.','شرح السرية والسلامة والتوافر بأمثلة.'),T('Use the words risk, threat, vulnerability and impact correctly.','Employer correctement risque, menace, vulnérabilité et impact.','استخدام مصطلحات الخطر والتهديد والثغرة والأثر بشكل صحيح.')],
 [T('Confidentiality: only the right people see data. Integrity: data stays correct and unaltered. Availability: systems work when needed. Around them: authentication (who are you?), authorization (what may you do?), accountability (actions are recorded) and non-repudiation (you cannot deny your action).','Confidentialité : seules les bonnes personnes voient les données. Intégrité : les données restent exactes. Disponibilité : les systèmes fonctionnent quand il le faut. Autour : authentification (qui es-tu ?), autorisation (que peux-tu faire ?), traçabilité et non-répudiation (on ne peut nier son action).','السرية: يرى البيانات الأشخاص المناسبون فقط. السلامة: تبقى البيانات صحيحة دون تعديل. التوافر: تعمل الأنظمة عند الحاجة. وحولها: التوثيق (من أنت؟) والتصريح (ماذا يحق لك؟) والمساءلة (تُسجَّل الأفعال) وعدم الإنكار (لا يمكنك إنكار فعلك).'),
  T('Least privilege: give only the access needed. Defense in depth: several layers, so one failure is not fatal. A threat (a phishing sender) uses a vulnerability (a weak password) and the impact (stolen grades) times its likelihood gives the risk.','Moindre privilège : donner seulement l’accès nécessaire. Défense en profondeur : plusieurs couches pour qu’une faille ne soit pas fatale. Une menace (un hameçonneur) exploite une vulnérabilité (mot de passe faible) ; impact (notes volées) × probabilité = risque.','أقل امتياز: امنح الوصول اللازم فقط. الدفاع المتعدد الطبقات: عدة طبقات حتى لا يكون فشل واحد قاتلاً. التهديد (منتحل) يستغل ثغرة (كلمة سر ضعيفة) والأثر (سرقة العلامات) × الاحتمال = الخطر.')],
 [G(T('Confidentiality','Confidentialité','السرية'),T('Only authorized people can read.','Seuls les autorisés lisent.','يقرأ المصرّح لهم فقط.')),G(T('Integrity','Intégrité','السلامة'),T('Data is accurate and unchanged.','Données exactes et inchangées.','البيانات صحيحة وغير معدلة.')),G(T('Least privilege','Moindre privilège','أقل امتياز'),T('Minimum access needed.','Accès minimal nécessaire.','أقل وصول لازم.'))],
 Q(T('At a fictional university, a student secretly changes their grade in the database. Which principle is broken?','Dans une université fictive, un étudiant modifie en secret sa note dans la base. Quel principe est violé ?','في جامعة خيالية يغيّر طالب علامته سراً في قاعدة البيانات. أي مبدأ انتُهك؟'),[T('Confidentiality','Confidentialité','السرية'),T('Integrity','Intégrité','السلامة'),T('Availability','Disponibilité','التوافر')],1,T('The data was altered, so integrity was broken.','Les données ont été modifiées : l’intégrité est violée.','تم تعديل البيانات، فانتُهكت السلامة.')),
 [Q(T('The exam server is offline during a ransomware incident. Which principle is hit?','Le serveur d’examens est hors ligne pendant un incident de rançongiciel. Quel principe est touché ?','خادم الامتحانات متوقف أثناء حادثة فدية. أي مبدأ تأثر؟'),[T('Availability','Disponibilité','التوافر'),T('Non-repudiation','Non-répudiation','عدم الإنكار')],0,T('Users cannot reach the system: availability.','Les utilisateurs n’accèdent plus au système : disponibilité.','لا يستطيع المستخدمون الوصول: التوافر.')),
  Q(T('Giving a lab assistant admin rights “just in case” breaks…','Donner les droits admin à un assistant « au cas où » viole…','منح مساعد المختبر صلاحيات المدير «تحسباً» يخالف…'),[T('Least privilege','Moindre privilège','أقل امتياز'),T('Encryption','Chiffrement','التشفير')],0,T('Give only the access needed for the job.','Donne seulement l’accès nécessaire au travail.','امنح فقط الوصول اللازم للعمل.'))],
 T('C, I and A guide every security decision; risk combines threat, vulnerability and impact.','C, I et A guident chaque décision ; le risque combine menace, vulnérabilité et impact.','تقود C وI وA كل قرار أمني، والخطر يجمع التهديد والثغرة والأثر.'),{diagram:'cia'}),

M('m3','mail',T('Common Cyber Threats','Menaces cybernétiques courantes','التهديدات السيبرانية الشائعة'),
 [T('Recognize phishing, malware, account takeover and other common threats.','Reconnaître hameçonnage, malwares, prise de contrôle de compte et autres menaces.','التعرف على التصيّد والبرمجيات الخبيثة وسرقة الحسابات وغيرها.'),T('Know warning signs and defensive habits.','Connaître les signes d’alerte et les bons réflexes.','معرفة علامات التحذير وعادات الدفاع.')],
 [T('Phishing and social engineering trick people, not machines. Malware (including ransomware) runs unwanted code. Password attacks guess or reuse stolen passwords. Account takeover and identity theft follow. Denial-of-service floods a service so real users cannot get in. Insiders, data breaches, unsafe downloads, fake websites and misconfigured systems complete the picture.','L’hameçonnage et l’ingénierie sociale trompent les gens, pas les machines. Les malwares (dont les rançongiciels) exécutent du code indésirable. Les attaques de mots de passe devinent ou réutilisent des mots de passe volés. Suivent prise de compte et usurpation d’identité. Le déni de service sature un service. Menaces internes, fuites de données, téléchargements risqués, faux sites et systèmes mal configurés complètent le tableau.','يخدع التصيّد والهندسة الاجتماعية الناس لا الآلات. تنفّذ البرمجيات الخبيثة (ومنها الفدية) شيفرة غير مرغوبة. تخمّن هجمات كلمات السر أو تعيد استخدام المسروق. يتبعها الاستيلاء على الحساب وانتحال الهوية. يغرق حجب الخدمة خدمة حتى لا يدخلها المستخدمون. ويكمل الصورة المطلعون الداخليون وتسريب البيانات والتنزيلات غير الآمنة والمواقع المزيفة والأنظمة سيئة الإعداد.'),
  T('Warning signs: urgency, unexpected attachments, requests for passwords, look-alike domains. Prevention: verify the sender another way, update software, use multi-factor authentication, download from official sources and back up your files.','Signes d’alerte : urgence, pièces jointes inattendues, demandes de mot de passe, domaines trompeurs. Prévention : vérifier l’expéditeur autrement, mettre à jour, activer l’authentification multifacteur, télécharger depuis les sources officielles et sauvegarder.','علامات التحذير: الاستعجال والمرفقات غير المتوقعة وطلب كلمات السر والنطاقات المشابهة. الوقاية: تحقق من المرسل بطريقة أخرى وحدّث البرامج وفعّل التحقق متعدد العوامل وحمّل من المصادر الرسمية واحتفظ بنسخ احتياطية.')],
 [G(T('Phishing','Hameçonnage','التصيّد'),T('A fake message that tricks you.','Faux message qui te piège.','رسالة مزيفة تخدعك.')),G(T('Ransomware','Rançongiciel','برمجية الفدية'),T('Malware that locks files for payment.','Malware qui bloque les fichiers contre rançon.','برمجية تقفل الملفات مقابل فدية.')),G(T('Denial of service','Déni de service','حجب الخدمة'),T('Overloading a service.','Surcharge d’un service.','إغراق خدمة بالطلبات.'))],
 Q(T('An email from “it-support@univ-helpdesk.example” says: “Your mailbox closes in 1 hour, confirm your password now.” Best action?','Un e-mail de « it-support@univ-helpdesk.example » dit : « Ta boîte ferme dans 1 h, confirme ton mot de passe ». Meilleure action ?','بريد من «it-support@univ-helpdesk.example» يقول: «سيُغلق بريدك خلال ساعة، أكّد كلمة سرك». أفضل إجراء؟'),[T('Reply with the password.','Répondre avec le mot de passe.','الرد بكلمة السر.'),T('Do not click; report it to the real IT office.','Ne pas cliquer ; le signaler au vrai service informatique.','عدم النقر والإبلاغ عنه لقسم تقنية المعلومات الحقيقي.'),T('Forward it to friends.','Le transférer à des amis.','تحويله إلى الأصدقاء.')],1,T('Urgency plus a password request is a phishing pattern. Report it through official channels.','Urgence + demande de mot de passe = schéma d’hameçonnage. Signale-le par les canaux officiels.','الاستعجال مع طلب كلمة السر نمط تصيّد. أبلغ عبر القنوات الرسمية.')),
 [Q(T('Ransomware mainly…','Un rançongiciel…','برمجية الفدية…'),[T('Locks or encrypts files and demands payment','Bloque ou chiffre des fichiers et exige une rançon','تقفل الملفات أو تشفرها وتطلب فدية'),T('Speeds up your Wi-Fi','Accélère ton Wi-Fi','تسرّع الواي فاي')],0,T('It holds your data hostage. Backups are the best defense.','Il prend tes données en otage. Les sauvegardes sont la meilleure défense.','تحتجز بياناتك. النسخ الاحتياطية أفضل دفاع.')),
  Q(T('Which is a phishing warning sign?','Quel est un signe d’hameçonnage ?','أي مما يلي علامة تصيّد؟'),[T('A look-alike domain and urgent tone','Un domaine trompeur et un ton urgent','نطاق مشابه ونبرة مستعجلة'),T('A message from a known teacher in class','Un message d’un prof connu en classe','رسالة من معلم معروف في الصف')],0,T('Look-alike addresses and pressure are classic signs.','Adresses trompeuses et pression : signes classiques.','العناوين المشابهة والضغط علامتان كلاسيكيتان.'))],
 T('Most threats exploit people first; slow down, verify, update and back up.','La plupart des menaces visent d’abord les gens : ralentis, vérifie, mets à jour, sauvegarde.','معظم التهديدات تستغل الناس أولاً: تمهّل وتحقق وحدّث واحتفظ بنسخ احتياطية.')),

M('m4','key',T('Passwords and Authentication','Mots de passe et authentification','كلمات السر والتوثيق'),
 [T('Create strong, unique passwords and understand password managers and MFA.','Créer des mots de passe forts et uniques, comprendre gestionnaires et MFA.','إنشاء كلمات سر قوية وفريدة وفهم مدراء كلمات السر والتحقق متعدد العوامل.'),T('Spot suspicious login notices and recover accounts safely.','Repérer les alertes de connexion suspectes et récupérer un compte en sécurité.','اكتشاف إشعارات الدخول المشبوهة واسترجاع الحسابات بأمان.')],
 [T('Long beats complex: a passphrase of four random words is strong and memorable. Never reuse passwords: one breach would open every account. A password manager creates and stores unique passwords for you. Multi-factor authentication (MFA) adds a second proof, such as an app code.','Long vaut mieux que complexe : quatre mots au hasard forment une phrase secrète solide et mémorisable. Ne réutilise jamais un mot de passe : une fuite ouvrirait tous tes comptes. Un gestionnaire en crée et en garde des uniques. L’authentification multifacteur (MFA) ajoute une seconde preuve, comme un code d’application.','الطويل أفضل من المعقد: عبارة من أربع كلمات عشوائية قوية وسهلة الحفظ. لا تعد استخدام كلمة سر: تسريب واحد يفتح كل حساباتك. يُنشئ مدير كلمات السر كلمات فريدة ويحفظها. ويضيف التحقق متعدد العوامل دليلاً ثانياً مثل رمز من تطبيق.'),
  T('Authentication proves who you are; authorization decides what you may do. Use official recovery options, protect your university account most, and treat unexpected “new login” alerts carefully: do not click their links, open the official site yourself and change your password.','L’authentification prouve qui tu es ; l’autorisation décide ce que tu peux faire. Utilise les options de récupération officielles, protège surtout ton compte universitaire et méfie-toi des alertes « nouvelle connexion » inattendues : ne clique pas, ouvre toi-même le site officiel et change ton mot de passe.','يثبت التوثيق من أنت ويحدد التصريح ما يحق لك فعله. استخدم خيارات الاسترجاع الرسمية واحمِ حسابك الجامعي أكثر من غيره وتعامل بحذر مع تنبيهات «دخول جديد» غير المتوقعة: لا تنقر روابطها وافتح الموقع الرسمي بنفسك وغيّر كلمة سرك.')],
 [G(T('Passphrase','Phrase secrète','عبارة سر'),T('A long password made of words.','Mot de passe long fait de mots.','كلمة سر طويلة من كلمات.')),G(T('MFA','MFA','التحقق متعدد العوامل'),T('Two or more proofs to log in.','Deux preuves ou plus pour se connecter.','دليلان أو أكثر لتسجيل الدخول.')),G(T('Credential reuse','Réutilisation d’identifiants','إعادة استخدام بيانات الدخول'),T('Using one password in many places.','Un même mot de passe partout.','استخدام كلمة سر واحدة في أماكن كثيرة.'))],
 {type:'pwtool'},
 [Q(T('Which is the best choice for a university account?','Quel est le meilleur choix pour un compte universitaire ?','ما أفضل خيار لحساب جامعي؟'),[T('A unique passphrase plus MFA','Une phrase secrète unique + MFA','عبارة سر فريدة مع التحقق متعدد العوامل'),T('The same password as my social media','Le même mot de passe que mes réseaux sociaux','نفس كلمة سر وسائل التواصل')],0,T('Unique and protected by a second factor is much safer.','Unique et protégé par un second facteur, c’est bien plus sûr.','الفريدة المدعومة بعامل ثانٍ أكثر أماناً بكثير.')),
  Q(T('Authorization answers…','L’autorisation répond à…','التصريح يجيب عن…'),[T('Who are you?','Qui es-tu ?','من أنت؟'),T('What are you allowed to do?','Que peux-tu faire ?','ماذا يُسمح لك أن تفعل؟')],1,T('Authentication proves identity; authorization sets permissions.','L’authentification prouve l’identité ; l’autorisation fixe les droits.','التوثيق يثبت الهوية والتصريح يحدد الصلاحيات.'))],
 T('Unique long passphrases, a manager and MFA protect most accounts.','Des phrases longues et uniques, un gestionnaire et la MFA protègent la plupart des comptes.','العبارات الطويلة الفريدة ومدير كلمات السر والتحقق متعدد العوامل تحمي أغلب الحسابات.')),

M('m5','maze',T('Network Security Fundamentals','Bases de la sécurité réseau','أساسيات أمن الشبكات'),
 [T('Describe IP addresses, ports, DNS, HTTP/HTTPS and firewalls.','Décrire adresses IP, ports, DNS, HTTP/HTTPS et pare-feu.','وصف عناوين IP والمنافذ وDNS وHTTP/HTTPS والجدران النارية.'),T('Explain public Wi-Fi risks, VPN limits and segmentation.','Expliquer les risques du Wi-Fi public, les limites d’un VPN et la segmentation.','شرح مخاطر الواي فاي العام وحدود VPN والتقسيم الشبكي.')],
 [T('A network connects devices. An IP address identifies a device and a port identifies a service on it (web: 80/443). DNS turns names into addresses. HTTPS encrypts web traffic, HTTP does not. Routers forward traffic between networks, switches connect devices inside one network and firewalls allow or block traffic by rules.','Un réseau relie des appareils. Une adresse IP identifie un appareil et un port un service (web : 80/443). Le DNS traduit les noms en adresses. HTTPS chiffre le trafic web, pas HTTP. Les routeurs relient les réseaux, les commutateurs relient les appareils d’un réseau et les pare-feu autorisent ou bloquent selon des règles.','تربط الشبكة الأجهزة. يحدد عنوان IP الجهاز ويحدد المنفذ الخدمة عليه (الويب: 80/443). يحوّل DNS الأسماء إلى عناوين. يشفّر HTTPS حركة الويب ولا يفعل HTTP ذلك. تمرّر الموجّهات الحركة بين الشبكات وتربط المبدّلات الأجهزة داخل شبكة وتسمح الجدران النارية أو تمنع بحسب قواعد.'),
  T('Public Wi-Fi can be watched or imitated: prefer HTTPS and avoid sensitive logins. A VPN encrypts your traffic to the VPN provider but does not make you anonymous or fix a malicious site. Segmentation splits a network (students, staff, servers) so a problem in one part does not spread everywhere.','Un Wi-Fi public peut être espionné ou imité : préfère HTTPS et évite les connexions sensibles. Un VPN chiffre ton trafic jusqu’au fournisseur, mais ne te rend pas anonyme ni ne corrige un site malveillant. La segmentation sépare un réseau (étudiants, personnel, serveurs) pour limiter la propagation.','قد تُراقَب شبكات الواي فاي العامة أو تُقلَّد: فضّل HTTPS وتجنب الدخول الحساس. يشفّر VPN حركتك حتى المزوّد لكنه لا يجعلك مجهولاً ولا يصلح موقعاً خبيثاً. يقسّم التقسيم الشبكي الشبكة (طلبة وموظفون وخوادم) حتى لا ينتشر الخلل.')],
 [G(T('Port','Port','منفذ'),T('A numbered door to a service.','Porte numérotée vers un service.','باب مرقّم إلى خدمة.')),G(T('DNS','DNS','DNS'),T('Name to address lookup.','Traduit un nom en adresse.','يحوّل الاسم إلى عنوان.')),G(T('Firewall','Pare-feu','جدار ناري'),T('Allows or blocks traffic by rules.','Autorise ou bloque selon des règles.','يسمح أو يمنع بحسب قواعد.'))],
 Q(T('A fictional campus web server only needs to serve websites. Which ports should the firewall allow from outside?','Un serveur web fictif de campus ne sert que des sites. Quels ports le pare-feu doit-il autoriser depuis l’extérieur ?','خادم ويب خيالي في الحرم يخدم مواقع فقط. أي منافذ يجب أن يسمح بها الجدار من الخارج؟'),[T('80 and 443 only','80 et 443 seulement','80 و443 فقط'),T('Every port','Tous les ports','كل المنافذ'),T('Only the database port','Seulement le port de la base','منفذ قاعدة البيانات فقط')],0,T('Open only what the service needs. Everything else stays blocked.','N’ouvre que ce dont le service a besoin. Le reste reste bloqué.','افتح فقط ما تحتاجه الخدمة وابقِ الباقي محجوباً.')),
 [Q(T('What does HTTPS add to HTTP?','Qu’ajoute HTTPS à HTTP ?','ماذا يضيف HTTPS إلى HTTP؟'),[T('Encryption of the traffic','Le chiffrement du trafic','تشفير الحركة'),T('Faster images','Images plus rapides','صور أسرع')],0,T('HTTPS protects data in transit from eavesdroppers.','HTTPS protège les données en transit contre l’espionnage.','يحمي HTTPS البيانات أثناء النقل من المتنصتين.')),
  Q(T('A VPN…','Un VPN…','شبكة VPN…'),[T('Makes you perfectly anonymous','Te rend parfaitement anonyme','تجعلك مجهولاً تماماً'),T('Encrypts traffic to the VPN, but has limits','Chiffre le trafic vers le VPN, avec des limites','تشفر الحركة نحو الخدمة ولها حدود')],1,T('A VPN shifts trust to the provider; it does not remove all risks.','Un VPN déplace la confiance vers le fournisseur ; il n’enlève pas tous les risques.','تنقل VPN الثقة إلى المزوّد ولا تزيل كل المخاطر.'))],
 T('Know the building blocks, open only needed ports and separate networks.','Connais les briques, n’ouvre que les ports utiles et sépare les réseaux.','اعرف اللبنات وافتح المنافذ اللازمة فقط وافصل الشبكات.'),{diagram:'net'}),

M('m6','cipher',T('Cryptography Basics','Bases de la cryptographie','أساسيات التشفير'),
 [T('Distinguish encoding, hashing and encryption.','Distinguer encodage, hachage et chiffrement.','التمييز بين الترميز والتجزئة والتشفير.'),T('Explain keys, signatures, certificates and HTTPS.','Expliquer clés, signatures, certificats et HTTPS.','شرح المفاتيح والتواقيع والشهادات وHTTPS.')],
 [T('Plaintext is readable data; ciphertext is the scrambled result of encryption with a key. Symmetric encryption uses one shared key. Asymmetric uses a public key to lock and a private key to unlock. Encoding (like Base64) changes format with no secret. Hashing makes a fixed fingerprint that cannot be reversed: it is not encryption.','Le texte clair est lisible ; le texte chiffré est le résultat brouillé d’un chiffrement avec une clé. Le chiffrement symétrique utilise une clé partagée. L’asymétrique utilise une clé publique pour verrouiller et une privée pour déverrouiller. L’encodage (Base64) change le format sans secret. Le hachage produit une empreinte fixe irréversible : ce n’est pas du chiffrement.','النص الواضح مقروء والنص المشفّر ناتج مخلوط بمفتاح. يستخدم التشفير المتماثل مفتاحاً مشتركاً واحداً. وغير المتماثل مفتاحاً عاماً للقفل وخاصاً للفتح. الترميز (مثل Base64) يغيّر الشكل دون سر. والتجزئة تنتج بصمة ثابتة لا يمكن عكسها: ليست تشفيراً.'),
  T('A digital signature proves who created data and that it was not changed. A certificate links a public key to a website, which is how HTTPS knows it is talking to the right server. Demos in this course are toys: real systems use well-tested libraries, never homemade crypto.','Une signature numérique prouve l’auteur et l’intégrité. Un certificat lie une clé publique à un site, ce qui permet à HTTPS de reconnaître le bon serveur. Les démos de ce cours sont des jouets : les vrais systèmes utilisent des bibliothèques éprouvées, jamais de la crypto maison.','يثبت التوقيع الرقمي منشئ البيانات وعدم تغييرها. تربط الشهادة مفتاحاً عاماً بموقع، وبهذا يعرف HTTPS أنه يتحدث مع الخادم الصحيح. العروض في هذا المقرر ألعاب تعليمية: الأنظمة الحقيقية تستخدم مكتبات مجرّبة ولا تبتكر تشفيراً بنفسها.')],
 [G(T('Hash','Hachage','تجزئة'),T('A one-way fingerprint of data.','Empreinte à sens unique.','بصمة أحادية الاتجاه للبيانات.')),G(T('Public key','Clé publique','مفتاح عام'),T('Shared openly to lock or verify.','Partagée pour verrouiller ou vérifier.','يُشارَك علناً للقفل أو التحقق.')),G(T('Certificate','Certificat','شهادة'),T('Proves a key belongs to a site.','Prouve qu’une clé appartient à un site.','تثبت أن المفتاح يخص موقعاً.'))],
 {type:'crypto'},
 [Q(T('Can you reverse a hash to get the original text?','Peut-on inverser un hachage pour retrouver le texte ?','هل يمكن عكس التجزئة لاستعادة النص الأصلي؟'),[T('No, it is one-way','Non, c’est à sens unique','لا، فهي أحادية الاتجاه'),T('Yes, with the public key','Oui, avec la clé publique','نعم بالمفتاح العام')],0,T('Hashing is one-way, so it is not encryption.','Le hachage est à sens unique : ce n’est pas du chiffrement.','التجزئة أحادية الاتجاه فليست تشفيراً.')),
  Q(T('In asymmetric encryption, which key stays secret?','En chiffrement asymétrique, quelle clé reste secrète ?','في التشفير غير المتماثل أي مفتاح يبقى سرياً؟'),[T('The private key','La clé privée','المفتاح الخاص'),T('The public key','La clé publique','المفتاح العام')],0,T('Only the owner keeps the private key.','Seul le propriétaire garde la clé privée.','المالك وحده يحتفظ بالمفتاح الخاص.'))],
 T('Encoding is not secret, hashing is one-way, encryption needs keys.','L’encodage n’est pas secret, le hachage est à sens unique, le chiffrement demande des clés.','الترميز ليس سراً والتجزئة أحادية والتشفير يحتاج مفاتيح.'),{diagram:'crypto'}),

M('m7','blocks',T('Operating System and Device Security','Sécurité des systèmes et appareils','أمن أنظمة التشغيل والأجهزة'),
 [T('Apply updates, accounts, permissions, backups and encryption.','Appliquer mises à jour, comptes, permissions, sauvegardes et chiffrement.','تطبيق التحديثات والحسابات والصلاحيات والنسخ الاحتياطي والتشفير.'),T('Practice file permissions in the simulated terminal.','S’exercer aux permissions de fichiers dans le terminal simulé.','التدرب على صلاحيات الملفات في الطرفية المحاكاة.')],
 [T('Install system and software updates quickly: they fix known holes. Use a standard account for daily work and an admin account only when needed. Keep antivirus or endpoint protection on, enable disk encryption, make 3-2-1 backups (3 copies, 2 media, 1 offsite) and never plug in unknown USB sticks.','Installe vite les mises à jour : elles corrigent des failles connues. Utilise un compte standard au quotidien et admin seulement si nécessaire. Garde un antivirus, active le chiffrement du disque, fais des sauvegardes 3-2-1 (3 copies, 2 supports, 1 hors site) et ne branche jamais une clé USB inconnue.','ثبّت تحديثات النظام والبرامج بسرعة فهي تسد ثغرات معروفة. استخدم حساباً عادياً يومياً وحساب المدير عند الحاجة فقط. أبقِ مكافح الفيروسات يعمل وفعّل تشفير القرص واعمل نسخاً احتياطية 3-2-1 (3 نسخ ووسيطان ونسخة خارج الموقع) ولا توصل أي USB مجهول.'),
  T('On Linux, ls -l shows permissions (read r, write w, execute x) for owner, group and others, and chmod changes them. Secure configuration means turning off what you do not use and changing default settings. Try these ideas in the Terminal Lab: it is a safe simulation.','Sous Linux, ls -l montre les permissions (lire r, écrire w, exécuter x) pour propriétaire, groupe et autres, et chmod les change. Une configuration sûre désactive ce qui est inutile et modifie les réglages par défaut. Essaie dans le labo Terminal : c’est une simulation sûre.','في لينكس يعرض ls -l الصلاحيات (قراءة r وكتابة w وتنفيذ x) للمالك والمجموعة والآخرين ويغيّرها chmod. الإعداد الآمن يعني إيقاف ما لا تستخدمه وتغيير الإعدادات الافتراضية. جرّب ذلك في مختبر الطرفية: محاكاة آمنة.')],
 [G(T('Patch','Correctif','تحديث أمني'),T('An update that fixes a flaw.','Mise à jour qui corrige une faille.','تحديث يصلح ثغرة.')),G(T('3-2-1 backup','Sauvegarde 3-2-1','نسخ 3-2-1'),T('3 copies, 2 media, 1 offsite.','3 copies, 2 supports, 1 hors site.','3 نسخ ووسيطان ونسخة خارجية.')),G(T('chmod','chmod','chmod'),T('Changes file permissions.','Change les permissions.','يغيّر صلاحيات الملف.'))],
 Q(T('A lab PC shows “updates available” for weeks. What is the best policy?','Un PC de labo affiche « mises à jour disponibles » depuis des semaines. Meilleure politique ?','حاسوب مختبر يظهر «تحديثات متوفرة» منذ أسابيع. أفضل سياسة؟'),[T('Install after testing, on a schedule','Installer après test, selon un calendrier','التثبيت بعد الاختبار وفق جدول'),T('Ignore them to avoid problems','Les ignorer pour éviter les soucis','تجاهلها لتفادي المشاكل')],0,T('Known flaws are used by attackers. Schedule and test updates.','Les failles connues sont exploitées. Planifie et teste les mises à jour.','يستغل المهاجمون الثغرات المعروفة. جدول التحديثات واختبرها.')),
 [Q(T('Which is a good backup rule?','Quelle est une bonne règle de sauvegarde ?','أي مما يلي قاعدة نسخ جيدة؟'),[T('3-2-1','3-2-1','3-2-1'),T('One copy on the same laptop','Une copie sur le même portable','نسخة واحدة على نفس الحاسوب')],0,T('Multiple copies in different places survive disasters.','Plusieurs copies à des endroits différents survivent aux sinistres.','نسخ متعددة في أماكن مختلفة تنجو من الكوارث.')),
  Q(T('Which command makes a file executable?','Quelle commande rend un fichier exécutable ?','أي أمر يجعل الملف قابلاً للتنفيذ؟'),[T('chmod +x','chmod +x','chmod +x'),T('cat','cat','cat')],0,T('chmod +x adds the execute permission.','chmod +x ajoute la permission d’exécution.','يضيف chmod +x صلاحية التنفيذ.'))],
 T('Update, limit privileges, encrypt and back up.','Mets à jour, limite les privilèges, chiffre et sauvegarde.','حدّث وقيّد الصلاحيات وشفّر واحتفظ بنسخ احتياطية.'),{term:'#/terminal'}),

M('m8','device',T('Web Security Fundamentals','Bases de la sécurité web','أساسيات أمن الويب'),
 [T('Explain how browsers and servers work, plus cookies and sessions.','Expliquer navigateurs, serveurs, cookies et sessions.','شرح عمل المتصفحات والخوادم والكعكات والجلسات.'),T('Understand input validation, access control and OWASP at a concept level.','Comprendre validation des entrées, contrôle d’accès et OWASP au niveau des concepts.','فهم التحقق من المدخلات والتحكم بالوصول وOWASP على المستوى المفاهيمي.')],
 [T('Your browser sends requests and a server answers. Client-side code runs on your device and can be seen or changed by you, so it can never be trusted for security. Server-side code runs on the server. A cookie lets the server recognize your session, so it must be protected.','Ton navigateur envoie des requêtes et un serveur répond. Le code côté client tourne chez toi, tu peux le voir ou le modifier : on ne peut donc pas lui faire confiance pour la sécurité. Le code côté serveur tourne sur le serveur. Un cookie permet au serveur de reconnaître ta session : il doit être protégé.','يرسل المتصفح طلبات ويرد الخادم. تعمل شيفرة العميل على جهازك ويمكنك رؤيتها وتغييرها فلا يُعتمد عليها للأمان. وتعمل شيفرة الخادم على الخادم. يتيح الكعك (cookie) للخادم تمييز جلستك فيجب حمايته.'),
  T('Good sites validate every input on the server, check access control on every request (not just hide buttons), and follow secure development habits. The OWASP Top 10 lists the most common web risks, such as broken access control and injection. If you find a problem, report it responsibly to the owner instead of exploiting it.','Les bons sites valident chaque entrée côté serveur, vérifient le contrôle d’accès à chaque requête (pas seulement cacher des boutons) et suivent de bonnes pratiques. Le Top 10 OWASP liste les risques web les plus courants, comme le contrôle d’accès défaillant et l’injection. Si tu trouves un problème, signale-le de façon responsable au propriétaire sans l’exploiter.','المواقع الجيدة تتحقق من كل مدخل على الخادم وتفحص التحكم بالوصول في كل طلب (لا تكتفي بإخفاء الأزرار) وتتبع ممارسات تطوير آمنة. تسرد قائمة OWASP العشرة أشيع مخاطر الويب مثل كسر التحكم بالوصول والحقن. وإذا وجدت مشكلة فأبلغ المالك بمسؤولية ولا تستغلها.')],
 [G(T('Session','Session','جلسة'),T('Your logged-in state on a site.','Ton état connecté sur un site.','حالتك كمسجّل دخول في موقع.')),G(T('Input validation','Validation des entrées','التحقق من المدخلات'),T('Checking data before using it.','Vérifier les données avant usage.','فحص البيانات قبل استخدامها.')),G(T('Access control','Contrôle d’accès','التحكم بالوصول'),T('Rules about who may open what.','Règles sur qui peut ouvrir quoi.','قواعد من يفتح ماذا.'))],
 Q(T('In a fictional campus portal, a page hides the “Admin” button from students, but the admin URL still works for anyone. What is wrong?','Dans un portail de campus fictif, une page cache le bouton « Admin » aux étudiants, mais l’URL admin marche pour tous. Quel est le problème ?','في بوابة حرم خيالية تُخفي الصفحة زر «المدير» عن الطلاب لكن رابط المدير يعمل للجميع. ما المشكلة؟'),[T('Access control is missing on the server','Le contrôle d’accès manque côté serveur','لا يوجد تحكم بالوصول على الخادم'),T('The button is too small','Le bouton est trop petit','الزر صغير جداً')],0,T('Hiding a button is not security. The server must check permissions.','Cacher un bouton n’est pas de la sécurité. Le serveur doit vérifier les droits.','إخفاء زر ليس أماناً. يجب أن يتحقق الخادم من الصلاحيات.')),
 [Q(T('Where should validation be enforced?','Où faut-il imposer la validation ?','أين يجب فرض التحقق؟'),[T('On the server (client checks are only a convenience)','Sur le serveur (côté client = confort)','على الخادم (فحص العميل للراحة فقط)'),T('Only in the browser','Seulement dans le navigateur','في المتصفح فقط')],0,T('Users can bypass browser checks.','Les contrôles du navigateur peuvent être contournés.','يمكن تجاوز فحوص المتصفح.')),
  Q(T('Found a flaw on a real site you do not own?','Une faille sur un vrai site qui n’est pas à toi ?','وجدت ثغرة في موقع حقيقي لا تملكه؟'),[T('Report it responsibly','La signaler de façon responsable','أبلغ عنها بمسؤولية'),T('Exploit it to prove it','L’exploiter pour le prouver','استغلها لإثبات ذلك')],0,T('Responsible disclosure protects users and you.','La divulgation responsable protège utilisateurs et toi.','الإفصاح المسؤول يحمي المستخدمين وأنت.'))],
 T('Never trust the client; validate and authorize on the server; disclose responsibly.','Ne fais jamais confiance au client ; valide et autorise côté serveur ; divulgue de façon responsable.','لا تثق بالعميل؛ تحقق وصرّح على الخادم وأفصح بمسؤولية.')),

M('m9','flag',T('Digital Forensics and Incident Response','Forensique numérique et réponse aux incidents','التحقيق الرقمي والاستجابة للحوادث'),
 [T('Describe evidence preservation, logs, timelines and the response phases.','Décrire préservation des preuves, journaux, chronologies et phases de réponse.','وصف حفظ الأدلة والسجلات والجداول الزمنية ومراحل الاستجابة.'),T('Analyze a fictional log and write a short incident report.','Analyser un journal fictif et rédiger un court rapport d’incident.','تحليل سجل خيالي وكتابة تقرير حادثة قصير.')],
 [T('Digital forensics collects and studies evidence without changing it. Preserve evidence (copies, hashes, notes) because integrity makes it trustworthy. Logs with timestamps tell the story of what happened and when. Incident response phases: detect, classify, contain, eradicate, recover, then document and learn.','La forensique collecte et étudie des preuves sans les modifier. Préserve-les (copies, empreintes, notes) car l’intégrité les rend fiables. Les journaux horodatés racontent ce qui s’est passé et quand. Phases de réponse : détecter, classer, contenir, éradiquer, rétablir, puis documenter et apprendre.','يجمع التحقيق الرقمي الأدلة ويدرسها دون تغييرها. احفظها (نسخ وبصمات وملاحظات) لأن السلامة تجعلها موثوقة. تروي السجلات ذات الطوابع الزمنية ما حدث ومتى. مراحل الاستجابة: اكتشاف وتصنيف واحتواء واستئصال واستعادة ثم توثيق وتعلّم.'),
  T('Report suspicious activity quickly to the right team. Good incident notes say what happened, when, what was affected and what was done. Never wipe or “clean” a machine before evidence is saved.','Signale vite toute activité suspecte à la bonne équipe. De bonnes notes disent ce qui s’est passé, quand, ce qui est touché et ce qui a été fait. N’efface jamais une machine avant d’avoir sauvé les preuves.','أبلغ عن النشاط المشبوه بسرعة للفريق المناسب. الملاحظات الجيدة تذكر ما حدث ومتى وما تأثر وما تم فعله. لا تمسح جهازاً قبل حفظ الأدلة.')],
 [G(T('Evidence integrity','Intégrité des preuves','سلامة الأدلة'),T('Proof that evidence was not changed.','Preuve que les preuves sont intactes.','إثبات أن الأدلة لم تتغير.')),G(T('Containment','Confinement','الاحتواء'),T('Stopping an incident from spreading.','Empêcher l’incident de s’étendre.','منع الحادثة من الانتشار.')),G(T('Timeline','Chronologie','الخط الزمني'),T('Events ordered by time.','Événements classés dans le temps.','أحداث مرتبة بالزمن.'))],
 {type:'incident'},
 [Q(T('You suspect a lab PC is infected. First step?','Tu soupçonnes un PC de labo infecté. Première étape ?','تشك بإصابة حاسوب مختبر. الخطوة الأولى؟'),[T('Isolate it from the network and report it','L’isoler du réseau et le signaler','عزله عن الشبكة والإبلاغ'),T('Reinstall it immediately','Le réinstaller immédiatement','إعادة تثبيته فوراً')],0,T('Contain first, keep evidence, then recover.','Contiens d’abord, garde les preuves, puis rétablis.','احتوِ أولاً واحفظ الأدلة ثم استعد.')),
  Q(T('Why do timestamps matter?','Pourquoi les horodatages comptent-ils ?','لماذا تهم الطوابع الزمنية؟'),[T('They order events into a timeline','Ils ordonnent les événements','ترتب الأحداث في خط زمني'),T('They decorate logs','Ils décorent les journaux','تزيّن السجلات')],0,T('A timeline shows cause and effect.','Une chronologie montre cause et effet.','يُظهر الخط الزمني السبب والنتيجة.'))],
 T('Preserve, investigate, contain, recover and document.','Préserve, enquête, contiens, rétablis et documente.','احفظ وحقّق واحتوِ واستعد ووثّق.')),

M('m10','academy',T('Privacy, Ethics, and Cyber Law','Vie privée, éthique et droit du numérique','الخصوصية والأخلاقيات والقانون السيبراني'),
 [T('Explain data minimization, consent and digital footprints.','Expliquer minimisation des données, consentement et empreinte numérique.','شرح تقليل البيانات والموافقة والبصمة الرقمية.'),T('Tell ethical hacking from unauthorized access and know where to check the law.','Distinguer le hacking éthique de l’accès non autorisé et savoir où vérifier la loi.','التمييز بين الاختراق الأخلاقي والدخول غير المصرّح ومعرفة أين تتحقق من القانون.')],
 [T('Personal data is information about you. Data minimization means collecting and sharing only what is needed. Consent should be informed and freely given. Your digital footprint is the trail you leave online, so think before posting. Respect copyright and treat others kindly: online harassment is harmful, and you can report and block it.','Les données personnelles sont des informations sur toi. La minimisation consiste à ne collecter et partager que le nécessaire. Le consentement doit être éclairé et libre. Ton empreinte numérique est la trace laissée en ligne : réfléchis avant de publier. Respecte le droit d’auteur et les autres : le harcèlement en ligne fait du mal, tu peux le signaler et bloquer.','البيانات الشخصية معلومات عنك. تقليل البيانات يعني جمع ومشاركة ما يلزم فقط. يجب أن تكون الموافقة مستنيرة وحرة. بصمتك الرقمية هي الأثر الذي تتركه على الإنترنت فتأمل قبل النشر. احترم حقوق الملكية وعامل الآخرين بلطف: التنمر الإلكتروني مؤذٍ ويمكنك الإبلاغ والحظر.'),
  T('Ethical hacking has written permission and a defined scope; unauthorized access is illegal even with good intentions. Laws differ by country and change. This course does not give legal advice: check current Tunisian legislation, official sources and your university’s IT policy, and ask your institution if unsure.','Le hacking éthique a une autorisation écrite et un périmètre ; l’accès non autorisé est illégal même avec de bonnes intentions. Les lois varient selon le pays et évoluent. Ce cours ne donne pas de conseil juridique : consulte la législation tunisienne en vigueur, les sources officielles et la charte informatique de ton université, et demande à ton établissement en cas de doute.','الاختراق الأخلاقي له إذن مكتوب ونطاق محدد، والدخول غير المصرّح غير قانوني حتى بحسن نية. تختلف القوانين بين الدول وتتغير. لا يقدّم هذا المقرر استشارة قانونية: راجع التشريعات التونسية السارية والمصادر الرسمية وسياسة جامعتك المعلوماتية واسأل مؤسستك عند الشك.')],
 [G(T('Data minimization','Minimisation des données','تقليل البيانات'),T('Collect only what is needed.','Ne collecter que le nécessaire.','جمع ما يلزم فقط.')),G(T('Consent','Consentement','الموافقة'),T('A clear, free agreement.','Accord clair et libre.','اتفاق واضح وحر.')),G(T('Responsible disclosure','Divulgation responsable','الإفصاح المسؤول'),T('Reporting flaws privately to the owner.','Signaler les failles au propriétaire.','إبلاغ المالك بالثغرات بسرية.'))],
 Q(T('A club app asks for your national ID number just to join a mailing list. What principle helps?','Une appli de club demande ton numéro d’identité pour t’inscrire à une liste de diffusion. Quel principe aide ?','تطبيق نادٍ يطلب رقم هويتك لمجرد الاشتراك في قائمة بريدية. أي مبدأ يساعد؟'),[T('Data minimization: do not give unnecessary data','Minimisation : ne pas donner de données inutiles','تقليل البيانات: لا تعطِ بيانات غير لازمة'),T('Share it, it is probably fine','Le donner, ça ira','أعطها فالأمر غالباً بخير')],0,T('Share only what is truly needed.','Ne partage que le strict nécessaire.','شارك ما هو لازم فعلاً فقط.')),
 [Q(T('What makes security testing legal and ethical?','Qu’est-ce qui rend un test de sécurité légal et éthique ?','ما الذي يجعل اختبار الأمان قانونياً وأخلاقياً؟'),[T('Written permission and clear scope','Autorisation écrite et périmètre clair','إذن مكتوب ونطاق واضح'),T('Curiosity alone','La seule curiosité','الفضول وحده')],0,T('Permission and scope are the foundation.','Autorisation et périmètre sont le fondement.','الإذن والنطاق هما الأساس.')),
  Q(T('Can you rely on this course for legal advice?','Peux-tu te fier à ce cours pour un avis juridique ?','هل يمكنك الاعتماد على هذا المقرر كاستشارة قانونية؟'),[T('No, check official sources and your institution','Non, consulte les sources officielles et ton établissement','لا، راجع المصادر الرسمية ومؤسستك'),T('Yes, completely','Oui, totalement','نعم تماماً')],0,T('Laws change and differ by place.','Les lois changent selon le lieu.','القوانين تتغير وتختلف حسب المكان.'))],
 T('Share less, ask permission, report responsibly and verify the law.','Partage moins, demande l’autorisation, signale avec responsabilité et vérifie la loi.','شارك أقل واطلب الإذن وأبلغ بمسؤولية وتحقق من القانون.')),

M('m11','wall',T('Security in the Real World','La sécurité dans le monde réel','الأمن في العالم الحقيقي'),
 [T('Explain policies, risk assessment and beginner threat modeling.','Expliquer politiques, évaluation des risques et modélisation des menaces.','شرح السياسات وتقييم المخاطر ونمذجة التهديدات للمبتدئين.'),T('Plan backups, monitoring and awareness for a fictional university.','Planifier sauvegardes, surveillance et sensibilisation pour une université fictive.','تخطيط النسخ الاحتياطي والمراقبة والتوعية لجامعة خيالية.')],
 [T('Organizations write security policies (rules), assess risk (what could go wrong, how likely, how bad) and run audits to check the rules are followed. Beginner threat modeling asks four questions: what are we protecting, from whom, how could it fail and what will we do about it?','Les organisations rédigent des politiques (règles), évaluent les risques (ce qui peut mal tourner, probabilité, gravité) et font des audits pour vérifier leur application. La modélisation des menaces pose quatre questions : que protège-t-on, contre qui, comment cela peut échouer, que fait-on ?','تكتب المؤسسات سياسات أمنية (قواعد) وتقيّم المخاطر (ما قد يسوء وكم احتماله وشدته) وتجري تدقيقاً للتأكد من الالتزام. يطرح نمذجة التهديدات أربعة أسئلة: ماذا نحمي ومن من وكيف قد يفشل وماذا سنفعل؟'),
  T('Backup and recovery plans keep the university running (business continuity). Monitoring spots problems early. Awareness training teaches everyone to spot phishing. Security is teamwork: students, teachers, IT and management all share it.','Les plans de sauvegarde et de reprise assurent la continuité d’activité. La surveillance repère tôt les problèmes. La sensibilisation apprend à tous à repérer l’hameçonnage. La sécurité est un travail d’équipe : étudiants, enseignants, informatique et direction.','تحافظ خطط النسخ الاحتياطي والاستعادة على استمرارية عمل الجامعة. تكشف المراقبة المشكلات مبكراً. وتعلّم التوعية الجميع اكتشاف التصيّد. الأمن عمل جماعي يشارك فيه الطلبة والأساتذة والتقنيون والإدارة.')],
 [G(T('Risk assessment','Évaluation des risques','تقييم المخاطر'),T('Estimating likelihood and impact.','Estimer probabilité et impact.','تقدير الاحتمال والأثر.')),G(T('Threat model','Modèle de menaces','نموذج التهديدات'),T('A structured view of what could go wrong.','Vue structurée de ce qui peut mal tourner.','نظرة منظمة لما قد يسوء.')),G(T('Business continuity','Continuité d’activité','استمرارية الأعمال'),T('Keeping services running.','Maintenir les services.','إبقاء الخدمات تعمل.'))],
 Q(T('A fictional university has a small budget. Which first measure gives the biggest protection for the cost?','Une université fictive a un petit budget. Quelle mesure donne la meilleure protection pour le coût ?','جامعة خيالية بميزانية صغيرة. أي إجراء يعطي أكبر حماية مقابل التكلفة؟'),[T('MFA for staff accounts and tested backups','MFA pour le personnel et sauvegardes testées','التحقق متعدد العوامل لحسابات الموظفين ونسخ احتياطية مختبرة'),T('A big lobby screen','Un grand écran dans le hall','شاشة كبيرة في الردهة'),T('A new logo','Un nouveau logo','شعار جديد')],0,T('Cheap, high-impact basics come first.','Les bases peu coûteuses et efficaces d’abord.','الأساسيات الرخيصة عالية الأثر أولاً.')),
 [Q(T('A threat model asks…','Un modèle de menaces demande…','يسأل نموذج التهديدات…'),[T('What are we protecting and from whom?','Que protège-t-on et contre qui ?','ماذا نحمي ومن ممن؟'),T('Which color is best?','Quelle couleur est la meilleure ?','ما أفضل لون؟')],0,T('It structures thinking about risk.','Il structure la réflexion sur le risque.','ينظم التفكير في المخاطر.')),
  Q(T('Backups are most useful when…','Les sauvegardes sont utiles quand…','تكون النسخ الاحتياطية أنفع عندما…'),[T('They are tested restores','Les restaurations sont testées','يُختبر استرجاعها'),T('Nobody ever checks them','Personne ne les vérifie','لا أحد يفحصها')],0,T('An untested backup may not work.','Une sauvegarde non testée peut échouer.','قد لا تعمل نسخة لم تُختبر.'))],
 T('Policies, risk thinking, backups and training make security practical.','Politiques, réflexion sur le risque, sauvegardes et formation rendent la sécurité concrète.','السياسات والتفكير بالمخاطر والنسخ والتدريب تجعل الأمن عملياً.'),{link:'#/defense',linkLabel:T('Open the Cyber Defense Simulator','Ouvrir le simulateur de défense','افتح محاكي الدفاع السيبراني')}),

M('m12','trophy',T('Careers and Learning Roadmap','Métiers et feuille de route','المهن وخارطة التعلم'),
 [T('Describe beginner-friendly cybersecurity roles.','Décrire des métiers accessibles de la cybersécurité.','وصف أدوار الأمن السيبراني المناسبة للمبتدئين.'),T('Plan next steps in networking, Linux and programming.','Planifier la suite : réseaux, Linux et programmation.','تخطيط الخطوات التالية في الشبكات ولينكس والبرمجة.')],
 [T('Roles include security analyst, SOC analyst (watches alerts), penetration tester (authorized testing), security engineer (builds defenses), forensics analyst, application security engineer, cloud security specialist, researcher and governance/risk/compliance (GRC) specialist.','Les rôles : analyste sécurité, analyste SOC (surveille les alertes), pentesteur (tests autorisés), ingénieur sécurité (construit les défenses), analyste forensique, ingénieur sécurité applicative, spécialiste cloud, chercheur et spécialiste gouvernance/risque/conformité.','تشمل الأدوار: محلل أمن ومحلل SOC (يراقب التنبيهات) ومختبر اختراق (اختبار مصرّح) ومهندس أمن (يبني الدفاعات) ومحلل تحقيق رقمي ومهندس أمن تطبيقات ومتخصص أمن سحابي وباحث ومتخصص حوكمة ومخاطر وامتثال.'),
  T('Roadmap: 1) networking basics, 2) Linux and the terminal, 3) one programming language such as Python, 4) operating-system concepts, 5) practice in legal labs and CTFs, 6) a first project. This introductory course does not make you a professional specialist; it is a starting point.','Feuille de route : 1) bases réseau, 2) Linux et terminal, 3) un langage comme Python, 4) concepts de systèmes, 5) pratique en labos légaux et CTF, 6) un premier projet. Ce cours d’introduction ne fait pas de toi un spécialiste ; c’est un point de départ.','خارطة الطريق: 1) أساسيات الشبكات 2) لينكس والطرفية 3) لغة برمجة مثل بايثون 4) مفاهيم أنظمة التشغيل 5) التدرب في مختبرات قانونية وCTF 6) مشروع أول. لا يجعلك هذا المقرر التمهيدي متخصصاً محترفاً بل هو نقطة بداية.')],
 [G(T('SOC','SOC','مركز عمليات الأمن'),T('Team that monitors security alerts.','Équipe qui surveille les alertes.','فريق يراقب التنبيهات الأمنية.')),G(T('Penetration tester','Pentesteur','مختبر اختراق'),T('Tests systems with permission.','Teste des systèmes avec autorisation.','يختبر الأنظمة بإذن.')),G(T('GRC','GRC','الحوكمة والمخاطر والامتثال'),T('Governance, risk and compliance.','Gouvernance, risque, conformité.','حوكمة ومخاطر وامتثال.'))],
 Q(T('You enjoy reading logs and spotting patterns. Which role fits?','Tu aimes lire des journaux et repérer des motifs. Quel rôle convient ?','تحب قراءة السجلات واكتشاف الأنماط. أي دور يناسبك؟'),[T('SOC analyst','Analyste SOC','محلل SOC'),T('Network cable installer only','Seulement installateur de câbles','مركّب كوابل فقط')],0,T('SOC analysts live in alerts and logs.','Les analystes SOC vivent dans les alertes et journaux.','يعيش محللو SOC بين التنبيهات والسجلات.')),
 [Q(T('Which skills help most as a foundation?','Quelles compétences servent le plus de base ?','أي المهارات أنفع كأساس؟'),[T('Networking, Linux and programming','Réseaux, Linux et programmation','الشبكات ولينكس والبرمجة'),T('Only memorizing tool names','Seulement mémoriser des noms d’outils','حفظ أسماء الأدوات فقط')],0,T('Fundamentals make every tool easier to learn.','Les bases facilitent chaque outil.','الأساسيات تسهّل تعلم كل أداة.')),
  Q(T('Does finishing this course make you a certified professional?','Terminer ce cours fait-il de toi un professionnel certifié ?','هل إنهاء هذا المقرر يجعلك محترفاً معتمداً؟'),[T('No, it is an introduction','Non, c’est une introduction','لا، إنه مقدمة'),T('Yes','Oui','نعم')],0,T('Keep learning and practicing legally.','Continue d’apprendre et de pratiquer légalement.','واصل التعلم والتدرب قانونياً.'))],
 T('Build fundamentals, practice legally and keep learning.','Construis les bases, pratique légalement et continue d’apprendre.','ابنِ الأساسيات وتدرّب قانونياً وواصل التعلم.'))
];
})();
